  "罫": [{w:"罫線",r:"괘선",d:"가로세로로 그은 선."},{w:"罫紙",r:"괘지",d:"미농지에 괘선을 박은 종이. 흔히, 공문서를 작성하는 데 쓴다."}],
  "卦": [{w:"占卦",r:"점괘",d:"점을 쳐서 나온 결과."},{w:"問卦",r:"문괘",d:"점괘로 길흉화복을 알아보는 일."}],
