  "葵": [{w:"天葵",r:"천규",d:"미나리아재빗과에 속한 개구리발톱의 생약명. 전초(全草)를 약용하며 소종, 해독, 이수에 효능이 있어 소변불리, 종독 따위를 치료하는 데 쓴다."},{w:"山葵",r:"산규",d:"십자화과의 여러해살이풀. 높이는 30cm 정도이며, 경엽은 심장 모양이고 근생엽은 긴 잎자루가 있고 심장 모양으로 가장자리에 톱니가 있다. 여름에 흰 꽃이 총상(總狀) 화서로 줄기 끝에 피고 열매는 장각과(長角果)를 맺는다. 땅속줄기는 양념 또는 약재로 쓴다. 시냇가에 나는데 한국, 사할린, 일본 등지에 분포한다."}],
  "窺": [{w:"窺見",r:"규견",d:"몰래 훔쳐봄."},{w:"爭窺",r:"쟁규",d:"서로 다투어 엿봄."}],
  "硅": [{w:"硅土",r:"규토",d:"석영을 주성분으로 하는 흙. 유리나 도자기를 만드는 재료로 쓴다."},{w:"硅化",r:"규화",d:"규소와 그보다 전기 음성도가 작은 원소가 화합하는 일."}],
  "橘": [{w:"柑橘",r:"감귤",d:"노란 껍질 속에 쌓여 있으며, 맛이 시고 새콤달콤한 겨울 과일."},{w:"金橘",r:"금귤",d:"껍질째 먹으며 새콤달콤한 맛이 나는 오렌지색의 둥글고 작은 열매 또는 그 나무."}],
