  "譏": [{w:"譏讒",r:"기참",d:"남을 비방함."},{w:"讒譏",r:"참기",d:"남을 헐뜯고 욕함."}],
  "肌": [{w:"肌理",r:"기리",d:"살갗의 결."},{w:"松肌",r:"송기",d:"소나무의 속껍질. 쌀가루와 함께 섞어서 떡이나 죽을 만들어 먹기도 한다."}],
  "綺": [{w:"羅綺",r:"나기",d:"곱고 아름다운 비단."},{w:"綺羅",r:"기라",d:"곱고 아름다운 비단. 또는 그 비단으로 지은 옷."}],
  "杞": [{w:"杞憂",r:"기우",d:"미래의 일에 대해 불필요한 걱정을 함. 또는 그 걱정."},{w:"杞柳",r:"기류",d:"버드나뭇과의 낙엽 관목. 높이는 1~3미터이며, 3월에 꽃이삭이 원주 모양으로 피고 열매는 삭과(蒴果)로 4~5월에 익는다. 가지는 껍질을 벗겨 버들고리나 키 따위를 만든다. 들이나 냇가에 나는데 한국, 우수리강, 일본, 중국 등지에 분포한다."}],
  "朞": [{w:"小朞",r:"소기",d:"사람이 죽은 지 1년 만에 지내는 제사."},{w:"服朞",r:"복기",d:"기년복을 입음."}],
  "崎": [{w:"崎嘴",r:"기취",d:"날카롭게 뾰족 튀어나온 물가의 언덕."},{w:"崎險",r:"기험",d:"‘기험하다’의 어근."}],
  "妓": [{w:"妓生",r:"기생",d:"(옛날에) 잔치나 술자리에서 손님에게 술을 따라 주며, 노래와 춤으로 흥을 돋우는 것을 직업으로 하던 여자."},{w:"妓女",r:"기녀",d:"(옛날에) 잔치나 술자리에서 손님에게 술을 따라 주며, 노래와 춤으로 흥을 돋우는 것을 직업으로 하던 여자."}],
  "伎": [{w:"伎藝",r:"기예",d:"육예(六藝)를 배움."},{w:"國伎",r:"국기",d:"‘서량기’를 달리 이르는 말."}],
  "羈": [{w:"羈檢",r:"기검",d:"단단히 단속함."},{w:"羈束",r:"기속",d:"얽어매어 묶음."}],
  "嗜": [{w:"嗜好",r:"기호",d:"즐기고 좋아함."},{w:"最嗜",r:"최기",d:"가장 즐기고 좋아함."}],
  "畸": [{w:"畸形",r:"기형",d:"사물의 구조나 생김새 등이 정상과 다른 모양."},{w:"畸零",r:"기령",d:"정전(井田)으로 구획하고 남은 땅."}],
  "拮": [{w:"拮抗",r:"길항",d:"서로 버티어 대항함."},{w:"拮据",r:"길거",d:"쉴 새 없이 일을 함."}],
