  "拏": [{w:"作拏",r:"작나",d:"소란을 일으킴."},{w:"紛拏",r:"분나",d:"어수선하고 소란스러움."}],
  "懦": [{w:"怯懦",r:"겁나",d:"(겁나고, 겁나는데, 겁나, 겁나서, 겁나니, 겁나면, 겁난, 겁나는, 겁날, 겁납니다, 겁났다, 겁나라)→ 겁나다"},{w:"懦弱",r:"나약",d:"의지가 굳세지 못함."}],
  "拿": [{w:"拿捕",r:"나포",d:"자기 나라의 바다를 불법으로 침범한 배를 붙잡음."},{w:"拿命",r:"나명",d:"붙잡아 오라는 명령."}],
  "儺": [{w:"儺者",r:"나자",d:"나례(儺禮)를 거행하는 사람들을 통틀어 이르는 말. 초라니, 방상시(方相氏), 아이 초라니, 지군(持軍) 등이 있다."},{w:"儺禮",r:"나례",d:"민가와 궁중에서, 음력 섣달그믐날에 묵은해의 마귀와 사신을 쫓아내려고 베풀던 의식. 본디 중국에서 시작한 것으로, 새해의 악귀를 쫓을 목적으로 행하다가 차츰 중국 칙사의 영접, 왕의 행행(行幸), 인산(因山) 때 따위에도 행하였다."}],
  "煖": [{w:"水煖爐",r:"수난로",d:"증기나 온수의 열을 발산하여 공기를 따뜻하게 하는 난방 장치."},{w:"煖肝煎",r:"난간전",d:"구기자, 당귀 따위를 넣어 만드는 약. 아랫배와 허리 부분이 차고 아픈 데 쓴다."}],
  "捏": [{w:"捏造",r:"날조",d:"사실이 아닌 것을 사실인 것처럼 거짓으로 꾸며 냄."},{w:"捏合",r:"날합",d:"사실이 아닌 것을 사실인 것처럼 거짓으로 꾸밈."}],
  "捺": [{w:"捺印",r:"날인",d:"지문이나 도장을 찍음."},{w:"捺章",r:"날장",d:"도장을 찍음."}],
  "衲": [{w:"名衲",r:"명납",d:"이름난 승려. ‘납(衲)’은 승복을 뜻하는 말로, 승려를 이른다."},{w:"老衲",r:"노납",d:"나이가 많은 승려."}],
  "囊": [{w:"背囊",r:"배낭",d:"물건을 넣어 등에 멜 수 있도록 만든 가방."},{w:"寢囊",r:"침낭",d:"겹으로 된 천 사이에 솜이나 깃털 등을 넣고 자루 모양으로 만들어 그 안에 들어가 잘 수 있도록 만든 것."}],
  "撚": [{w:"左撚",r:"좌연",d:"실을 왼쪽으로 꼬는 것. 실의 꼬임선이 알파벳 제트(Z) 자로 나타난다."},{w:"撚絲",r:"연사",d:"몇 가닥의 실을 꼬아서 만든 실. 강도가 높고 탄성이 좋다."}],
  "涅": [{w:"涅槃",r:"열반",d:"불교에서, 진리를 깨달아 번뇌에서 벗어나고 평화로운 상태에 도달한 경지."},{w:"涅齒",r:"열치",d:"이를 검게 물들이는 일. 또는 그 이."}],
  "弩": [{w:"弓弩",r:"궁노",d:"활과 쇠뇌를 아울러 이르는 말."},{w:"伏弩",r:"복노",d:"쇠뇌를 쏘던 복병."}],
  "駑": [{w:"罷駑",r:"파노",d:"지쳐서 아주 둔하여진 말이라는 뜻으로, 쓸모없는 둔재(鈍才)를 이르는 말."},{w:"駑下",r:"노하",d:"둔한 말 아래라는 뜻으로, 남에게 자기를 낮추어 이르는 말."}],
  "膿": [{w:"化膿",r:"화농",d:"상처가 난 피부나 몸속 장기에 고름이 생김."},{w:"排膿",r:"배농",d:"곪은 곳을 째거나 따서 고름을 빼냄."}],
  "撓": [{w:"屈撓",r:"굴요",d:"마음이나 기개가 굽혀지거나 꺾임."},{w:"撓屈",r:"요굴",d:"휘어 굽음. 또는 휘어 굽힘."}],
  "訥": [{w:"訥辯",r:"눌변",d:"말이 자꾸 막히고 유창하지 않는 말솜씨."},{w:"訥言",r:"눌언",d:"더듬거리는 말."}],
  "紐": [{w:"紐帶",r:"유대",d:"둘 이상을 서로 이어 주거나 결합하게 하는 것. 또는 그런 관계."},{w:"結紐",r:"결뉴",d:"끈을 맴. 또는 얽어 맺음."}],
  "匿": [{w:"匿名",r:"익명",d:"이름을 밝히지 않음. 또는 숨긴 이름이나 대신 쓰는 이름."},{w:"隱匿",r:"은닉",d:"남의 물건이나 범죄를 저지른 사람을 감춤."}],
  "蛋": [{w:"蛋白",r:"단백",d:"조류나 파충류 따위에서, 알의 난황과 난각막 사이에 있는 젤 모양의 물질. 주로 단백질과 물로 이루어졌으며, 배(胚)를 보호하여 발생할 때 양분이 된다."},{w:"皮蛋",r:"피단",d:"중국요리의 하나. 오리알을 석회 따위가 함유된 진흙과 왕겨에 넣어 삭힌 요리이다."}],
  "簞": [{w:"瓢簞",r:"표단",d:"조롱박이나 둥근 박을 반으로 쪼개어 만든 작은 바가지."},{w:"一簞",r:"일단",d:"대나무로 만든 그릇이나 도시락 한 개. 또는 거기에 담은 음식."}],
  "緞": [{w:"緋緞",r:"비단",d:"명주실로 짠, 광택이 나고 빛깔이 우아하며 가볍고 촉감이 부드러운 천."},{w:"禮緞",r:"예단",d:"결혼할 때 신부가 시댁 어른들에게 드리는 돈이나 물건."}],
  "撻": [{w:"撻罰",r:"달벌",d:"종아리를 때려 벌을 줌. 또는 그 벌."},{w:"推撻",r:"추달",d:"매로 때림."}],
  "疸": [{w:"黃疸",r:"황달",d:"온몸과 눈 등이 누렇게 되는 병."},{w:"五疸",r:"오달",d:"황달(黃疸), 곡달(穀疸), 주달(酒疸), 여로달(女勞疸), 황한(黃汗)의 다섯 가지 황달."}],
  "憺": [{w:"憺畏",r:"담외",d:"벌벌 떨면서 두려워함."}],
