  "澹": [{w:"慘澹",r:"참담",d:"끔찍하고 절망적임."},{w:"暗澹",r:"암담",d:"‘암담하다’의 어근."}],
  "痰": [{w:"赤痰",r:"적담",d:"피가 섞여 붉은빛을 띤 가래."},{w:"痰聲",r:"담성",d:"가래가 목구멍에서 끓는 소리."}],
  "譚": [{w:"民譚",r:"민담",d:"예로부터 사람들 사이에서 전해져 내려오는 이야기."},{w:"奏譚",r:"주담",d:"어떤 이야기를 임금에게 아룀."}],
  "遝": [{w:"至遝",r:"지답",d:"한군데로 몰려들거나 몰려옴."},{w:"遝至",r:"답지",d:"한군데로 몰려들거나 몰려옴."}],
  "撞": [{w:"撞球",r:"당구",d:"네모난 대 위에 공을 놓고 긴 막대기로 쳐서 맞히는 것으로 이기고 지는 것을 가리는 실내 경기."},{w:"撞着",r:"당착",d:"말이나 행동 따위의 앞뒤가 맞지 않음."}],
  "棠": [{w:"棠梨",r:"당리",d:"팥배나무의 열매."},{w:"甘棠",r:"감당",d:"장미과의 낙엽 활엽 교목. 높이는 10미터 정도이며, 잎은 어긋나고 달걀 모양 또는 타원형이다. 4~5월에 흰 꽃이 방상(房狀) 화서로 피고 열매는 타원형의 이과(梨果)로 10월에 익는다. 목재는 기구재나 땔나무로 쓰고 열매는 식용한다. 한국, 일본, 만주 등지에 분포한다."}],
  "螳": [{w:"螳螂",r:"당랑",d:"사마귓과의 곤충을 통틀어 이르는 말."},{w:"螳螂力",r:"당랑력",d:"사마귀가 수레바퀴를 막는 힘이라는 뜻으로, 아주 약한 힘이나 병력(兵力)을 이르는 말."}],
  "擡": [{w:"擡頭",r:"대두",d:"어떤 문제나 현상이 새롭게 나타남."},{w:"擡肩",r:"대견",d:"숨이 몹시 차서 어깨를 들먹거리는 증상."}],
  "袋": [{w:"包袋",r:"포대",d:"종이나 가죽, 천 등으로 만든 큰 자루."},{w:"負袋",r:"부대",d:"종이나 가죽, 천 등으로 만든 큰 자루."}],
  "搗": [{w:"賃搗",r:"임도",d:"삯을 받고 찧어 주는 방아."},{w:"搗精",r:"도정",d:"곡식을 찧거나 쓿음."}],
  "鍍": [{w:"鍍金",r:"도금",d:"물체의 겉에 금이나 은과 같은 금속을 얇게 입힘."},{w:"電鍍",r:"전도",d:"전기 분해의 원리를 이용하여 금속의 표면에 다른 금속의 얇은 막을 입히는 일."}],
  "蹈": [{w:"足蹈",r:"족도",d:"발로 뜀."},{w:"蹈襲",r:"도습",d:"옛 정책, 수법, 방식 따위를 그대로 본받아 좇음."}],
  "賭": [{w:"賭博",r:"도박",d:"돈 또는 재물을 걸고 화투, 트럼프, 마작 등으로 내기를 함."},{w:"加賭",r:"가도",d:"지주나 마름이 도조(賭租)의 기준을 올려서 매기던 일."}],
  "萄": [{w:"葡萄",r:"포도",d:"달면서도 약간 신맛이 나는 작은 열매가 뭉쳐서 송이를 이루는 보라색 과일."},{w:"葡萄酒",r:"포도주",d:"포도를 원료로 하여 만든 술."}],
  "禱": [{w:"祈禱",r:"기도",d:"바라는 바가 이루어지도록 절대적 존재 혹은 신앙의 대상에게 비는 것."},{w:"默禱",r:"묵도",d:"눈을 감고 조용히 마음속으로 비는 기도."}],
