  "屠": [{w:"屠殺",r:"도살",d:"사람을 마구 죽임."},{w:"屠畜",r:"도축",d:"고기를 얻기 위하여 가축을 잡아 죽임."}],
  "淘": [{w:"淘汰",r:"도태",d:"여럿 가운데에서 필요 없거나 적당하지 않다고 여겨지는 것들을 없앰."},{w:"淘金",r:"도금",d:"사금을 일어서 금을 골라냄."}],
