  "堵": [{w:"安堵",r:"안도",d:"사는 곳에서 평안하게 잘 지냄. 또는 평안히 지낼 수 있는 곳."},{w:"堵列",r:"도열",d:"여러 사람이 길게 줄지어 섬. 또는 그런 행렬."}],
