  "瀆": [{w:"冒瀆",r:"모독",d:"말이나 행동으로 어떤 대상을 부끄럽고 수치스럽게 만듦."},{w:"瀆冒",r:"독모",d:"신성한 것을 범하여 더럽힘."}],
  "沌": [{w:"混沌",r:"혼돈",d:"마구 뒤섞여서 구분이 되지 않고 규칙이나 질서가 없음. 또는 그런 상태."},{w:"混沌感",r:"혼돈감",d:"마구 뒤섞여 있어 갈피를 잡을 수 없는 느낌."}],
