  "瞳": [{w:"瞳孔",r:"동공",d:"빛의 양에 따라 크기가 달라지는 눈알 가운데의 검은 부분."},{w:"綠瞳",r:"녹동",d:"푸른 눈동자라는 뜻으로, 서양 사람의 눈을 이르는 말."}],
  "胴": [{w:"胴體",r:"동체",d:"물체의 중심을 이루는 부분."},{w:"胴間",r:"동간",d:"몸통의 길이."}],
  "憧": [{w:"憧憬",r:"동경",d:"어떤 대상을 마음속으로 간절히 그리워하고 바람."},{w:"憧憧",r:"동동",d:"‘동동하다’의 어근."}],
  "兜": [{w:"兜率",r:"도솔",d:"육욕천의 넷째 하늘. 수미산의 꼭대기에서 12만 유순(由旬) 되는 곳에 있는, 미륵보살이 사는 곳으로, 내외(內外) 두 원(院)이 있는데, 내원은 미륵보살의 정토이며, 외원은 천계 대중이 환락하는 장소라고 한다."},{w:"禪兜",r:"선도",d:"인간과 그 밖의 모든 생물."}],
  "痘": [{w:"水痘",r:"수두",d:"열이 나고 가려우며 피부에 붉은 점과 물집이 생기는, 바이러스성 전염병."},{w:"痘面",r:"두면",d:"천연두를 앓아서 얽은 얼굴."}],
  "臀": [{w:"臀部",r:"둔부",d:"뒤쪽 허리 아래에서 양쪽 허벅지로 이어지는, 둥글고 살이 많은 부분."},{w:"臀上",r:"둔상",d:"궁중에서, ‘엉덩이’를 이르던 말."}],
  "遁": [{w:"隱遁",r:"은둔",d:"세상에서 일어나는 일을 피하여 숨음."},{w:"遁甲",r:"둔갑",d:"요술을 부려서 자기 몸을 감추거나 다른 것으로 바꿈."}],
  "橙": [{w:"橙色",r:"등색",d:"귤이나 등자 껍질의 빛깔과 같이 붉은빛을 약간 띤 누런색."},{w:"橙黃",r:"등황",d:"타이, 미얀마, 캄보디아, 스리랑카 따위에서 나는 식물의 수지로 만든 선명한 황색의 채색."}],
  "邏": [{w:"邏卒",r:"나졸",d:"(옛날에) 마을을 순찰하고 죄인을 잡아들이는 일을 맡아 하던 계급이 낮은 군인."},{w:"偵邏",r:"정라",d:"형세를 살피기 위하여 둘러봄. 또는 그런 사람."}],
  "螺": [{w:"螺絲",r:"나사",d:"한 방향으로 비틀어 돌려 물체를 조이는 데 쓰는 홈이 파인 못."},{w:"螺旋",r:"나선",d:"겉모양이 소라 껍데기처럼 한 방향으로 빙빙 돌면서 꼬인 것."}],
  "懶": [{w:"懶怠",r:"나태",d:"행동이나 성격이 느리고 게으름."},{w:"懶農",r:"나농",d:"농사일을 게을리함."}],
