  "駱": [{w:"駱駝",r:"낙타",d:"사막 지대에서 사람이 타거나 짐을 나르는 데 쓰이는, 등에 큰 혹이 있는 동물."},{w:"朱駱",r:"주락",d:"낙마의 붉은 갈기로 만든 삭모. 깃발이나 창의 윗부분에 단다."}],
  "烙": [{w:"烙印",r:"낙인",d:"불에 달구어 찍는 쇠로 된 도장. 또는 그것으로 찍은 표시."},{w:"烙殺",r:"낙살",d:"사람을 단근질하여 죽임."}],
