  "瀾": [{w:"波瀾",r:"파란",d:"크고 작은 물결."},{w:"回瀾",r:"회란",d:"넘어가거나 맴도는 사납고 큰 파도."}],
  "鸞": [{w:"鸞車",r:"난거",d:"중국의 순(舜) 임금이 타던 수레."},{w:"赤鸞",r:"적란",d:"빛깔이 붉은 난조(鸞鳥). 봉황과 비슷하다고 하는 상상의 새이다."}],
  "剌": [{w:"水剌",r:"수라",d:"(높이는 말로) 궁중에서, 임금에게 올리는 밥."},{w:"瓦剌",r:"와라",d:"‘오이라트’의 음역어."}],
  "辣": [{w:"惡辣",r:"악랄",d:"성질이 악하고 잔인함."},{w:"辣腕",r:"날완",d:"매서운 수완."}],
  "籃": [{w:"搖籃",r:"요람",d:"아기를 태우고 흔들어 놀게 하거나 재우는, 바구니처럼 생긴 물건."},{w:"竹籃",r:"죽람",d:"대로 엮어 만든 바구니."}],
  "蠟": [{w:"蜜蠟",r:"밀랍",d:"꿀벌이 벌집을 만들기 위하여 분비하는 물질."},{w:"蠟花",r:"납화",d:"밀랍을 물들여 만든 꽃."}],
