  "狼": [{w:"狼狽",r:"낭패",d:"일이 계획하거나 기대한 대로 되지 않아 곤란한 상황에 빠짐."},{w:"狼抗",r:"낭항",d:"이리처럼 성질이 거칠고, 사납게 마구 반항기가 있음."}],
