  "粱": [{w:"靑粱",r:"청량",d:"차조의 하나. 이삭에 털이 있고 알이 잘며 빛이 푸르다."},{w:"黃粱",r:"황량",d:"찰기가 없는 조. 알이 굵고 빛이 노르며 끈기가 적다."}],
