  "戾": [{w:"返戾",r:"반려",d:"윗사람이나 위 기관에 제출한 문서 등을 처리하지 않고 되돌려줌."},{w:"拂戾",r:"불려",d:"(불려, 불려서, 불렸다, 불려라)→ 불리다1, 불리다2"}],
  "濾": [{w:"濾過",r:"여과",d:"액체 속에 들어 있는 알갱이나 가라앉은 물질을 걸러 내는 일."},{w:"濾速",r:"여속",d:"단위 시간 동안에 여재를 통과하는 여과액의 평균 속도."}],
