  "逞": [{w:"不逞",r:"불령",d:"원한, 불만, 불평 따위를 품고서 어떠한 구속도 받지 아니하고 제 마음대로 행동함. 또는 그런 사람."},{w:"逞兵",r:"영병",d:"뛰어나게 강한 병사."}],
  "鈴": [{w:"啞鈴",r:"아령",d:"길지 않은 막대기의 양 끝에 둥글고 무거운 것이 달려 있어, 양손에 하나씩 들고 팔 운동을 하는 운동 기구."},{w:"金鈴",r:"금령",d:"금으로 만든 방울."}],
