  "悧": [{w:"怜悧",r:"영리",d:"‘영리하다’의 어근."}],
  "籬": [{w:"缺籬",r:"결리",d:"귀퉁이 한쪽이 부서진 울타리."},{w:"竹籬",r:"죽리",d:"굵은 대나무를 쪼개서 결어 만들거나, 대를 심어 이루어진 울타리."}],
  "釐": [{w:"釐革",r:"이혁",d:"뜯어고쳐 정리함."},{w:"釐正",r:"이정",d:"문서나 글을 정리하여 바로잡음."}],
  "俚": [{w:"俚歌",r:"이가",d:"항간에 유행하는 속된 노래."},{w:"俚語",r:"이어",d:"항간(巷間)에 떠돌며 쓰이는 속된 말."}],
