  "痢": [{w:"痢疾",r:"이질",d:"변에 희거나 피가 섞인 점액이 섞여 나오며 자주 변을 보고 싶은 증상이 있는 전염병."},{w:"冷痢",r:"냉리",d:"몸이 차고 습하여 생긴 이질. 배가 아프고 곱똥이 나오며 뒤가 땅긴다."}],
