  "吝": [{w:"吝嗇",r:"인색",d:"물건이나 돈 등을 몹시 아껴 씀씀이가 너그럽지 못함."},{w:"儉吝",r:"검린",d:"‘검린하다’의 어근."}],
  "鱗": [{w:"片鱗",r:"편린",d:"한 조각의 비늘이라는 뜻으로, 사물의 매우 작은 한 부분."},{w:"小鱗",r:"소린",d:"작은 비늘."}],
  "燐": [{w:"鬼燐",r:"귀린",d:"밤에 무덤이나 축축한 땅 또는 고목이나 낡고 오래된 집에서 인 따위의 작용으로 저절로 번쩍이는 푸른빛의 불꽃."},{w:"燐光",r:"인광",d:"복사 광선에 노출된 물질이, 자극하는 복사 에너지가 사라진 후에도 계속하여 내는 발광. 흰인 따위에서 볼 수 있다."}],
  "躪": [{w:"蹂躪",r:"유린",d:"남의 권리나 인격을 마구 억누르거나 짓밟음."},{w:"征躪",r:"정린",d:"남을 정복하여 짓밟음."}],
