  "笠": [{w:"着笠",r:"착립",d:"초립이나 삿갓을 씀."},{w:"黑笠",r:"흑립",d:"옻칠을 한 갓. 어두운 흑갈색이다."}],
  "粒": [{w:"粒子",r:"입자",d:"물질을 이루는 아주 작은 크기의 물체."},{w:"顆粒",r:"과립",d:"둥글고 작은 알갱이."}],
  "寞": [{w:"寂寞",r:"적막",d:"아무 소리 없이 조용하고 쓸쓸함."},{w:"落寞",r:"낙막",d:"‘낙막하다’의 어근."}],
  "輓": [{w:"輓章",r:"만장",d:"죽은 사람을 애도하여 쓴 글."},{w:"輓歌",r:"만가",d:"사람의 죽음을 슬퍼하며 부르는 노래."}],
