  "蔓": [{w:"蔓延",r:"만연",d:"(비유적으로) 전염병이나 나쁜 현상 등이 널리 퍼짐."},{w:"綠蔓",r:"녹만",d:"푸른 풀덤불."}],
  "鰻": [{w:"風鰻",r:"풍만",d:"말린 뱀장어."},{w:"養鰻",r:"양만",d:"뱀장어를 기름."}],
