  "彎": [{w:"彎屈",r:"만굴",d:"활 모양으로 굽음."},{w:"彎環",r:"만환",d:"둥근 모양. 또는 그 모양의 물건."}],
  "挽": [{w:"挽留",r:"만류",d:"어떤 일을 하지 못하게 붙잡고 말림."},{w:"挽回",r:"만회",d:"잃은 것, 잘못된 것, 뒤떨어진 것 등을 원래의 상태로 되돌리거나 그에 맞먹는 다른 것으로 대신함."}],
  "瞞": [{w:"欺瞞",r:"기만",d:"남을 속임."},{w:"瞞着",r:"만착",d:"남의 눈을 속여 넘김."}],
  "抹": [{w:"一抹",r:"일말",d:"약간."},{w:"抹消",r:"말소",d:"기록되어 있는 사실 등을 지워 없애 버림."}],
  "沫": [{w:"飛沫",r:"비말",d:"날아 흩어지거나 튀어 오르는 물방울."},{w:"浮沫",r:"부말",d:"물이 다른 물이나 물체에 부딪쳐서 생기는 거품."}],
  "襪": [{w:"洋襪",r:"양말",d:"발을 보호하거나 추위를 막기 위해 실이나 천으로 만들어 발에 신는 물건."},{w:"寶襪",r:"보말",d:"아름다운 버선."}],
  "芒": [{w:"芒種",r:"망종",d:"일 년 중 곡식의 씨를 뿌리기에 가장 좋다는 날로 이십사절기의 하나. 6월 6일경이다. 이 시기에 모내기와 보리 베기가 이루어진다."},{w:"光芒",r:"광망",d:"비치는 빛살."}],
  "惘": [{w:"悵惘",r:"창망",d:"‘창망하다’의 어근."},{w:"憫惘",r:"민망",d:"‘민망하다’의 어근."}],
  "煤": [{w:"煤煙",r:"매연",d:"공기 중의 오염 물질로 연료가 탈 때 나오는 그을음이 섞인 검은 연기."},{w:"煙煤",r:"연매",d:"연기 속에 섞여 나오는 검은 가루. 또는 구들장 밑이나 굴뚝 따위에 끈끈하게 엉키어 붙은 그을음."}],
  "罵": [{w:"罵倒",r:"매도",d:"다른 사람을 심하게 비난하며 몰아세움."},{w:"面罵",r:"면매",d:"면전(面前)에서 꾸짖음."}],
  "邁": [{w:"邁進",r:"매진",d:"어떤 일을 온 마음과 힘을 다하여 해 나감."},{w:"邁德",r:"매덕",d:"힘써 덕을 닦음."}],
