  "寐": [{w:"夢寐",r:"몽매",d:"잠을 자면서 꿈을 꿈. 또는 그 꿈."},{w:"監寐",r:"감매",d:"자나 깨나 언제나."}],
  "萌": [{w:"萌芽",r:"맹아",d:"풀이나 나무에 새로 돋아 나오는 싹."},{w:"未萌",r:"미맹",d:"초목의 싹이 아직 트지 않음."}],
