  "杳": [{w:"杳然",r:"묘연",d:"‘묘연하다’의 어근."},{w:"杳乎",r:"묘호",d:"‘묘호하다’의 어근."}],
  "渺": [{w:"渺漫",r:"묘만",d:"끝없이 넓음."},{w:"渺遠",r:"묘원",d:"‘묘원하다’의 어근."}],
  "巫": [{w:"巫女",r:"무녀",d:"귀신을 받들어 점치고 굿을 하는 것을 직업으로 하는 여자."},{w:"巫俗",r:"무속",d:"귀신을 섬겨 점을 보거나 굿을 하여 재앙을 물리치고 복을 비는 풍속."}],
