  "誣": [{w:"誣說",r:"무설",d:"없는 사실을 있는 것처럼 꾸며 댄 소문."},{w:"構誣",r:"구무",d:"터무니없는 일을 꾸미어 모함함."}],
  "蚊": [{w:"蚊群",r:"문군",d:"모여서 날아다니는 모기의 무리."},{w:"蚊雷",r:"문뢰",d:"모기가 많이 모여 시끄럽게 왱왱거림."}],
