  "薇": [{w:"薔薇",r:"장미",d:"줄기에 가시가 있고 오월이나 유월에 향기롭게 피는 빨간색, 하얀색, 노란색 등의 꽃이 피는 나무. 또는 그 꽃."},{w:"薇湯",r:"미탕",d:"고비를 넣고 끓인 국."}],
  "媚": [{w:"阿媚",r:"아미",d:"남의 환심을 사거나 잘 보이려고 알랑거림. 또는 그런 말이나 짓."},{w:"媚悅",r:"미열",d:"남의 환심을 사거나 잘 보이려고 알랑거림. 또는 그런 말이나 짓."}],
