  "謐": [{w:"靜謐",r:"정밀",d:"고요하고 편안함."},{w:"安謐",r:"안밀",d:"‘안밀하다’의 어근."}],
  "膊": [{w:"肩膊",r:"견박",d:"어깨의 바깥쪽 위팔의 윗머리 부분."},{w:"上膊",r:"상박",d:"어깨에서 팔꿈치까지의 부분."}],
  "搏": [{w:"搏動",r:"박동",d:"맥박이 뜀."},{w:"脈搏",r:"맥박",d:"심장 박동에 따라 나타나는 동맥의 주기적인 움직임."}],
  "縛": [{w:"束縛",r:"속박",d:"어떤 행동을 하거나 권리를 자유롭게 행사하지 못하도록 강제로 막음."},{w:"結縛",r:"결박",d:"끈이나 줄 등으로 움직이거나 빠져나가지 못하게 둘러 묶음."}],
  "箔": [{w:"金箔",r:"금박",d:"다른 물건을 장식하기 위해 금이나 금빛 나는 물건을 종이처럼 얇게 만든 것."},{w:"銀箔",r:"은박",d:"은 또는 은과 같은 빛깔의 재료를 종이와 같이 얇게 만든 것."}],
  "撲": [{w:"撲滅",r:"박멸",d:"모조리 잡아 없앰."},{w:"撲筆",r:"박필",d:"붓을 집어 던짐."}],
  "剝": [{w:"剝奪",r:"박탈",d:"남의 재물이나 권리, 자격 등을 강제로 빼앗음."},{w:"剝製",r:"박제",d:"동물의 가죽을 벗기고 썩지 않게 한 뒤 그 안에 솜 등을 넣어 원래의 모양대로 만듦. 또는 그렇게 만든 물건."}],
  "珀": [{w:"明珀",r:"명박",d:"빛깔이 누런빛을 띠면서 붉은, 송진을 닮은 호박(琥珀)."},{w:"琥珀",r:"호박",d:"지질 시대 나무의 진 따위가 땅속에 묻혀서 탄소, 수소, 산소 따위와 화합하여 굳어진 누런색 광물. 투명하거나 반투명하고 광택이 있으며, 불에 타기 쉽고 마찰하면 전기가 생긴다. 장식품이나 절연재 따위로 쓴다."}],
  "樸": [{w:"樸學",r:"박학",d:"질박(質朴)한 학문."},{w:"敦樸",r:"돈박",d:"인정이 많고 두터우며 성품이 꾸민 데가 없이 수수함."}],
  "粕": [{w:"豆粕",r:"두박",d:"콩에서 기름을 짜내고 남은 찌꺼기. 가축의 사료나 비료 따위로 쓴다."},{w:"酒粕",r:"주박",d:"재강에 물을 타서 모주를 짜내고 남은 찌꺼기."}],
  "駁": [{w:"反駁",r:"반박",d:"어떤 의견이나 주장 등에 반대하여 말함."},{w:"面駁",r:"면박",d:"얼굴을 마주 하여 꾸짖거나 창피를 줌."}],
  "槃": [{w:"涅槃",r:"열반",d:"불교에서, 진리를 깨달아 번뇌에서 벗어나고 평화로운 상태에 도달한 경지."},{w:"涅槃門",r:"열반문",d:"열반에 들어가는 문."}],
