  "絆": [{w:"絆籠",r:"반롱",d:"얽어매어 가두고 자유를 속박함."},{w:"絆緣",r:"반연",d:"얽히어 맺어지는 인연."}],
  "畔": [{w:"湖畔",r:"호반",d:"호수를 둘러싼 가장자리."},{w:"海畔",r:"해반",d:"바닷물과 땅이 서로 닿은 곳이나 그 근처."}],
  "蟠": [{w:"蟠龍",r:"반룡",d:"아직 승천하지 아니하고 땅에 서려 있는 용."},{w:"龍蟠",r:"용반",d:"용이 서렸다는 뜻으로, 호걸이 민간에 숨어 있음을 이르는 말."}],
