  "攀": [{w:"登攀",r:"등반",d:"높은 산을 오름."},{w:"攀登",r:"반등",d:"험한 산이나 높은 곳의 정상에 이르기 위하여 오름."}],
  "拌": [{w:"攪拌",r:"교반",d:"휘저어 섞음."},{w:"攪拌機",r:"교반기",d:"열을 고루 잘 퍼지게 하거나, 재료를 잘 뒤섞기 위하여 휘젓는 기구나 기계."}],
  "跋": [{w:"跋文",r:"발문",d:"책의 마지막 부분에 간략한 책의 내용과 지은이를 칭찬하는 내용을 적은 글."},{w:"跋扈",r:"발호",d:"권력을 마음대로 휘두르며 함부로 행동함."}],
