  "魃": [{w:"旱魃",r:"한발",d:"가뭄을 맡고 있다는 귀신."},{w:"炎魃",r:"염발",d:"오랫동안 계속하여 비가 내리지 않아 메마른 날씨."}],
  "醱": [{w:"醱酵",r:"발효",d:"효모나 미생물에 의해 유기물이 분해되고 변화하는 작용."},{w:"醱酵法",r:"발효법",d:"효모나 미생물을 이용하여 유기물을 분해하고 변화시키는 방법."}],
  "潑": [{w:"潑皮",r:"발피",d:"일정한 직업이 없이 못된 짓만 하면서 떠돌아다니는 무리."},{w:"潑墨",r:"발묵",d:"글씨나 그림에서, 먹물이 번져 퍼지는 일. 또는 그렇게 하는 기법."}],
