  "膀": [{w:"膀胱",r:"방광",d:"오줌을 모아 두었다가 몸 밖으로 내보내는, 주머니 모양의 신체 기관."},{w:"膀胱計",r:"방광계",d:"방광의 압력과 용적을 측정하여 방광의 효율성을 연구하는 데 쓰는 기계."}],
  "幇": [{w:"幇助",r:"방조",d:"다른 사람이 범죄를 저지르는 것을 도와주는 행위."},{w:"助幇",r:"조방",d:"오입판에서, 남녀 사이의 일을 주선하고 잔심부름 따위를 함. 또는 그런 일."}],
