  "帛": [{w:"幣帛",r:"폐백",d:"결혼할 때 신부가 처음으로 시부모에게 큰절을 하고 올리는, 대추와 포 등의 음식."},{w:"金帛",r:"금백",d:"금과 비단을 아울러 이르는 말."}],
