  "菩": [{w:"菩薩",r:"보살",d:"불교에서, 위로는 부처를 따르고 아래로는 중생을 이끄는, 부처의 다음가는 성인."},{w:"菩提",r:"보리",d:"불교 최고의 이상인 불타 정각의 지혜."}],
