  "狩": [{w:"狩獵",r:"수렵",d:"사람이 산이나 들에 나가 총이나 활 등으로 짐승을 잡는 일."},{w:"巡狩",r:"순수",d:"임금이 나라 안을 두루 살피며 돌아다니던 일."}],
