  "穗": [{w:"麥穗",r:"맥수",d:"보리의 이삭."},{w:"燈穗",r:"등수",d:"‘등불’을 이르는 말. 등불의 불꽃 모양이 이삭과 같다는 데에서 나온 말이다."}],
  "瘦": [{w:"日瘦",r:"일수",d:"나날이 여윔."},{w:"瘦身",r:"수신",d:"마르고 야윈 몸."}],
