  "夙": [{w:"夙世",r:"숙세",d:"지나간 시대."},{w:"夙夜",r:"숙야",d:"이른 아침과 깊은 밤."}],
  "菽": [{w:"菽麥",r:"숙맥",d:"세상 물정을 잘 모르는 어리석은 사람."},{w:"菽粟",r:"숙속",d:"콩과 조라는 뜻으로, ‘곡류’를 이르는 말."}],
  "塾": [{w:"里塾",r:"이숙",d:"마을 안에 있는 글방."},{w:"義塾",r:"의숙",d:"공익을 위하여 의연금을 모아 세운 교육 기관."}],
  "醇": [{w:"醇化",r:"순화",d:"사람을 가르쳐 생각이나 감정을 바람직하게 변하게 함."},{w:"化醇",r:"화순",d:"변화하여 순수하게 됨."}],
