  "丞": [{w:"政丞",r:"정승",d:"조선 시대에, 나랏일을 맡아보던 가장 높은 벼슬."},{w:"丞相",r:"승상",d:"옛 중국의 벼슬. 우리나라의 정승에 해당한다."}],
  "柿": [{w:"月下柿",r:"월하시",d:"떫은 감 품종의 하나. 전라남도 나주가 주산지로 10월 하순이 수확기이다. 과실은 원형에 가까운 편원형(扁圓形)이며, 무게는 200~250그램 정도에 크기가 크다. 과피는 주황색을 띠고, 과육이 등황색을 띤다. 육질은 치밀하며 유연하다."},{w:"高種柿",r:"고종시",d:"떫은 감 품종의 한 종류. 경북 상주가 주산지로 10월 하순이 수확기이다. 과실은 장원형이며, 무게가 200그램 정도로 중과종이다. 과피 색은 황홍색이고, 과육은 진한 주황색을 띤다. 육질이 점질로 유연하며 숙시 및 건시용으로 품질이 좋다."}],
  "匙": [{w:"匙箸",r:"시저",d:"숟가락과 젓가락을 아울러 이르는 말."},{w:"揷匙",r:"삽시",d:"제사 지낼 때 숟가락을 메에 꽂음. 또는 그런 의식."}],
  "媤": [{w:"媤宅",r:"시댁",d:"(높이는 말로) 남편의 부모가 사는 집. 또는 남편의 집안."},{w:"媤家",r:"시가",d:"남편의 부모가 사는 집. 또는 남편의 집안."}],
  "弑": [{w:"弑害",r:"시해",d:"부모나 대통령, 임금 등의 지위가 높은 사람을 죽임."},{w:"弑殺",r:"시살",d:"부모나 임금 등을 죽임."}],
  "猜": [{w:"猜忌",r:"시기",d:"남이 잘되는 것을 싫어하여 미워함."},{w:"猜惡",r:"시오",d:"시기하고 미워함."}],
