  "蝕": [{w:"月蝕",r:"월식",d:"달이 지구의 그림자에 가려 그 전부나 일부분이 보이지 않게 되는 현상."},{w:"日蝕",r:"일식",d:"달이 태양의 일부나 전부를 가리는 현상."}],
