  "啞": [{w:"聾啞",r:"농아",d:"듣지 못하거나 말하지 못하는 사람."},{w:"啞鈴",r:"아령",d:"길지 않은 막대기의 양 끝에 둥글고 무거운 것이 달려 있어, 양손에 하나씩 들고 팔 운동을 하는 운동 기구."}],
