  "秧": [{w:"秧針",r:"앙침",d:"갓 자란 볏모."},{w:"拔秧",r:"발앙",d:"싹을 뽑아 버림."}],
  "鴦": [{w:"鴛鴦",r:"원앙",d:"부리가 짧고 물갈퀴가 있으며 수컷은 몸 빛깔이 흰색, 주황색, 붉은 갈색 등으로 아름답고 암컷은 갈색 바탕에 회색 얼룩이 있는, 주로 물에서 생활하는 새."},{w:"鴦衾",r:"앙금",d:"원앙을 수놓은 이불."}],
