  "腋": [{w:"腋導",r:"액도",d:"겨드랑이를 붙잡아 걷는 것을 도움."},{w:"兩腋",r:"양액",d:"양쪽 겨드랑이."}],
  "縊": [{w:"自縊",r:"자액",d:"스스로 목을 매어 죽음."},{w:"縊死",r:"액사",d:"목을 매어 죽음."}],
