  "猿": [{w:"犬猿",r:"견원",d:"개와 원숭이라는 뜻으로, 서로 사이가 나쁜 두 사람을 비유적으로 이르는 말."},{w:"猿公",r:"원공",d:"‘원숭이’를 의인화하여 높여 이르는 말."}],
