  "蹂": [{w:"蹂躪",r:"유린",d:"남의 권리나 인격을 마구 억누르거나 짓밟음."}],
  "喩": [{w:"比喩",r:"비유",d:"어떤 것을 효과적으로 설명하기 위해 그것과 비슷한 다른 것에 빗대어 설명하는 일. 또는 그런 설명 방법."},{w:"隱喩",r:"은유",d:"문학에서, 직접 말하지 않고 다른 말로 바꾸어 암시적으로 나타내는 방법."}],
  "愉": [{w:"愉快",r:"유쾌",d:"즐겁고 상쾌함."},{w:"怡愉",r:"이유",d:"즐겁고 기쁨."}],
  "宥": [{w:"宥和",r:"유화",d:"상대방을 너그럽게 받아들여 사이좋게 지냄."},{w:"恩宥",r:"은유",d:"남에게 은혜를 베풀어 용서함."}],
