  "椅": [{w:"椅子",r:"의자",d:"사람이 엉덩이와 허벅지를 대고 걸터앉는 데 쓰는 기구."},{w:"竹椅",r:"죽의",d:"대를 결어서 만든 의자."}],
  "擬": [{w:"模擬",r:"모의",d:"실제와 똑같이 따라 해 봄. 또는 그런 일."},{w:"擬古",r:"의고",d:"옛것을 본뜸."}],
  "誼": [{w:"友誼",r:"우의",d:"친구나 형제 또는 두 집단 사이의 친밀한 감정과 의리."},{w:"情誼",r:"정의",d:"서로 사귀어 친해진 정."}],
  "餌": [{w:"藥餌",r:"약이",d:"약이 되는 음식."},{w:"食餌",r:"식이",d:"동물이 살아가기 위하여 먹어야 할 거리. 또는 사육하는 가축에게 주는 먹을거리."}],
  "姨": [{w:"姨母",r:"이모",d:"어머니의 언니나 여동생을 이르거나 부르는 말."},{w:"姨從",r:"이종",d:"이모의 아들이나 딸과의 친족 관계. 또는 그런 관계에 있는 사람."}],
