  "靭": [{w:"靭帶",r:"인대",d:"뼈와 뼈가 맞닿는 부분에 있는, 끈이나 띠 모양의 결합 조직."},{w:"靭性",r:"인성",d:"재료의 질긴 정도. 외부에서 잡아당기거나 누르는 힘 때문에 갈라지거나 늘어나지 않고 견디는 성질을 이른다."}],
  "咽": [{w:"嗚咽",r:"오열",d:"목메어 욺. 또는 목메어 우는 울음."},{w:"感咽",r:"감열",d:"감격하여 목메어 욺."}],
  "湮": [{w:"湮滅",r:"인멸",d:"흔적도 없이 모두 없어짐. 또는 그렇게 없앰."},{w:"湮沒",r:"인몰",d:"자취도 없이 모두 없어짐. 또는 그렇게 없앰."}],
  "溢": [{w:"海溢",r:"해일",d:"갑자기 바닷물이 크게 일어서 육지로 넘쳐 들어오는 것. 또는 그런 현상."},{w:"充溢",r:"충일",d:"가득 차서 넘침."}],
  "佚": [{w:"佚民",r:"일민",d:"세상을 등지고 숨어 사는 백성."},{w:"佚遊",r:"일유",d:"마음대로 편안히 즐기고 놂."}],
  "剩": [{w:"剩餘",r:"잉여",d:"쓰고 난 후에 남은 것."},{w:"過剩",r:"과잉",d:"수나 양, 정도가 필요로 하는 것보다 지나치게 많아서 남음."}],
  "孕": [{w:"孕胎",r:"잉태",d:"배 속에 아이나 새끼가 생김."},{w:"孕母",r:"잉모",d:"아이를 밴 여자."}],
  "疵": [{w:"瑕疵",r:"하자",d:"물건 등의 깨지거나 잘못된 부분."},{w:"疵病",r:"자병",d:"흠이나 결점."}],
  "仔": [{w:"仔豚",r:"자돈",d:"새끼 돼지."},{w:"仔蟲",r:"자충",d:"알에서 나온 후 아직 다 자라지 아니한 벌레."}],
  "蔗": [{w:"蔗境",r:"자경",d:"담화나 문장 또는 사건 따위가 점점 재미있어지는 대목."},{w:"甘蔗",r:"감자",d:"볏과의 여러해살이풀. 높이는 2~4미터이며, 수수와 비슷하나 마디와 마디 사이가 짧다. 잎은 가늘고 긴데 긴 선 모양이다. 줄기의 꼭대기에 회백색 꽃이 원추(圓錐) 화서로 핀다. 줄기에서 짠 즙으로 설탕을 만든다. 인도 갠지스강 유역이 원산지로 열대, 아열대에서 재배한다."}],
  "炙": [{w:"散炙",r:"산적",d:"길쭉길쭉하게 썬 고기와 채소에 양념을 한 뒤 꼬챙이에 꿰어서 구운 음식."},{w:"膾炙",r:"회자",d:"칭찬을 받으며 사람의 입에 자주 오르내림."}],
  "煮": [{w:"煮乾",r:"자건",d:"삶아서 말림."},{w:"煮汁",r:"자즙",d:"끓인 즙."}],
  "藉": [{w:"憑藉",r:"빙자",d:"무엇의 힘을 빌리거나 의지함."},{w:"慰藉",r:"위자",d:"위로하고 도와줌."}],
  "瓷": [{w:"瓷器",r:"자기",d:"진흙으로 빚어서 아주 높은 온도로 구운 그릇."},{w:"靑瓷",r:"청자",d:"진흙을 빚어 유약을 발라 높은 열로 구운, 푸른빛을 띠는 자기."}],
  "炸": [{w:"炸裂",r:"작렬",d:"포탄이나 폭탄 등이 터져서 산산이 퍼짐."},{w:"炸發",r:"작발",d:"화약이 터짐."}],
  "勺": [{w:"銀勺",r:"은작",d:"은으로 만든 구기."},{w:"勺水",r:"작수",d:"한 작의 물이라는 뜻으로, 한 모금의 물을 이르는 말."}],
