  "綽": [{w:"綽號",r:"작호",d:"남들이 별명처럼 지어서 불러 주는 이름."},{w:"巡綽",r:"순작",d:"순찰하여 경계함."}],
  "嚼": [{w:"咀嚼",r:"저작",d:"음식을 입에 넣고 씹음."},{w:"爛嚼",r:"난작",d:"음식을 잘 씹음."}],
  "芍": [{w:"芍藥",r:"작약",d:"작약과의 여러해살이풀을 통틀어 이르는 말. 꽃이 크고 아름다워 정원에 관상용으로 재배한다. 백작약, 산작약, 적작약, 호작약 따위가 있다."},{w:"贈芍",r:"증작",d:"작약(芍藥)을 선물로 바친다는 뜻으로, 남녀가 서로 사랑을 표시함을 비유적으로 이르는 말."}],
  "雀": [{w:"孔雀",r:"공작",d:"긴 꼬리 깃을 부채 모양으로 펴면 매우 화려하고 아름다운 무늬가 있는, 열대 지방의 큰 새."},{w:"麻雀",r:"마작",d:"네 사람이 글씨나 숫자가 새겨진 136개의 패를 가지고 짝을 맞추어 승부를 겨루는 놀이."}],
  "鵲": [{w:"鵲語",r:"작어",d:"까치의 지저귀는 소리. 흔히 기쁜 일이 있을 조짐으로 여긴다."},{w:"鵲報",r:"작보",d:"까치가 지저귀는 소리라는 뜻으로, ‘길조’를 이르는 말."}],
  "盞": [{w:"燈盞",r:"등잔",d:"기름을 담아 등불을 켜는 데에 쓰는 그릇."},{w:"添盞",r:"첨잔",d:"술이 들어 있는 잔에 술을 더 따름."}],
  "棧": [{w:"棧道",r:"잔도",d:"험한 벼랑 같은 곳에 낸 길. 선반처럼 달아서 낸다."},{w:"木棧",r:"목잔",d:"나무로 사다리처럼 놓은 길."}],
  "箴": [{w:"箴言",r:"잠언",d:"사람의 인생에 교훈이 되는 말."},{w:"動箴",r:"동잠",d:"사물잠(四勿箴)의 하나. 예(禮)가 아니면 움직이지 말라는 경계이다."}],
  "簪": [{w:"金簪",r:"금잠",d:"금으로 만든 비녀."},{w:"玉簪",r:"옥잠",d:"옥으로 만든 비녀."}],
  "檣": [{w:"前檣",r:"전장",d:"뱃머리 쪽에 있는 돛대."},{w:"檣頭",r:"장두",d:"돛대의 맨 꼭대기."}],
  "薔": [{w:"薔薇",r:"장미",d:"줄기에 가시가 있고 오월이나 유월에 향기롭게 피는 빨간색, 하얀색, 노란색 등의 꽃이 피는 나무. 또는 그 꽃."},{w:"白薔薇",r:"백장미",d:"흰색 장미."}],
  "漿": [{w:"乳漿",r:"유장",d:"젖 성분에서 단백질과 지방을 빼고 남은 부분."},{w:"牛漿",r:"우장",d:"천연두를 예방하기 위하여 우두에서 뽑아낸 면역성 액체."}],
  "醬": [{w:"醋醬",r:"초장",d:"식초를 넣은 간장."},{w:"醬庫",r:"장꼬",d:"궁중에서, ‘장독대’를 이르던 말."}],
  "杖": [{w:"棍杖",r:"곤장",d:"(옛날에) 죄를 진 사람의 엉덩이나 허벅지를 때리던 나무로 된 길고 넙적한 도구."},{w:"杖責",r:"장책",d:"태형으로 벌함."}],
  "匠": [{w:"巨匠",r:"거장",d:"특정 분야에서 능력이나 실력이 뛰어난 사람."},{w:"匠人",r:"장인",d:"손으로 물건을 만드는 일을 직업으로 하는 사람."}],
  "仗": [{w:"天仗",r:"천장",d:"임금의 의장(儀仗)."},{w:"甲仗",r:"갑장",d:"갑옷과 창검 따위의 병기."}],
  "齋": [{w:"書齋",r:"서재",d:"책을 갖추어 두고 책을 읽거나 글을 쓰는 방."},{w:"齋七",r:"재칠",d:"사람이 죽은 뒤 49일 동안 이레마다 행하는 재."}],
  "滓": [{w:"殘滓",r:"잔재",d:"쓰고 남은 찌꺼기."},{w:"魚滓",r:"어재",d:"살을 발라내었거나 기름을 짜고 난 물고기의 찌꺼기. 주로 비료로 쓴다."}],
  "錚": [{w:"錚盤",r:"쟁반",d:"보통 다른 그릇을 받쳐 드는 데에 쓰는, 높이가 매우 낮고 바닥이 넓고 큰 그릇."},{w:"擊錚",r:"격쟁",d:"징이나 꽹과리를 침."}],
  "狙": [{w:"狙擊",r:"저격",d:"어떤 대상을 겨냥하여 총을 쏨."},{w:"狙公",r:"저공",d:"‘원숭이’를 달리 이르는 말."}],
  "豬": [{w:"豬毛",r:"저모",d:"돼지의 털."},{w:"兒豬",r:"아저",d:"어린 새끼 돼지. 또는 고기로 먹을 어린 돼지."}],
  "箸": [{w:"下箸",r:"하저",d:"젓가락을 댄다는 뜻으로, 음식을 먹음을 이르는 말."},{w:"火箸",r:"화저",d:"화로에 꽂아 두고 불덩이를 집거나 불을 헤치는 데 쓰는 쇠로 만든 젓가락."}],
  "咀": [{w:"咀嚼",r:"저작",d:"음식을 입에 넣고 씹음."},{w:"咀嚼力",r:"저작력",d:"음식을 입에 넣고 씹는 힘."}],
  "詛": [{w:"詛呪",r:"저주",d:"남에게 불행한 일이 일어나도록 빌고 바람. 또는 그렇게 해서 일어난 불행한 일."},{w:"呪詛",r:"주저",d:"남에게 재앙이나 불행이 일어나도록 빌고 바람. 또는 그렇게 하여서 일어난 재앙이나 불행."}],
  "躇": [{w:"躊躇",r:"주저",d:"선뜻 결정하여 행동하지 못하고 망설임."},{w:"躊躇痕",r:"주저흔",d:"자살하려는 사람이 한 번에 치명상을 만들지 못하고 여러 차례 자해하여 생긴 흔적."}],
  "邸": [{w:"邸宅",r:"저택",d:"크기가 아주 큰 집."},{w:"官邸",r:"관저",d:"정부에서 장관급 이상의 고위 공무원들이 살도록 마련해 준 집."}],
  "觝": [{w:"角觝",r:"각저",d:"고구려 때에, 하류층에서 하던 놀이의 하나. 두 사람이 씨름하듯이 맞붙어 힘을 겨루거나 또는 여러 가지 기예와 활쏘기, 말타기 따위를 겨루었다."},{w:"蝸角觝",r:"와각저",d:"하찮은 일로 벌이는 싸움을 비유적으로 이르는 말."}],
  "嫡": [{w:"嫡女",r:"적녀",d:"정실이 낳은 딸."},{w:"嫡兄",r:"적형",d:"첩에게서 난 아들이 정실에게서 난 형을 이르는 말."}],
  "謫": [{w:"謫客",r:"적객",d:"귀양살이를 하는 사람."},{w:"謫落",r:"적락",d:"죄를 지어 관직에서 퇴직당함."}],
  "狄": [{w:"狄人",r:"적인",d:"중국 북쪽의 야만족."},{w:"戎狄",r:"융적",d:"중국에서 서쪽 오랑캐와 북쪽 오랑캐를 아울러 이르던 말."}],
