  "貼": [{w:"白貼",r:"백첩",d:"옻칠을 하지 않은 아주 큰 부채. 살이 40∼50개이다."},{w:"貼金",r:"첩금",d:"구리나 쇠 따위에 얇은 금판을 싸서 입히는 일."}],
  "疊": [{w:"重疊",r:"중첩",d:"거듭해서 겹침."},{w:"疊疊",r:"첩첩",d:"여러 물건이 포개짐."}],
